import numpy as np


def r(x):
    # Map x in [0, 1] to sqrt(x), which is always >= x and stays within [0, 1].
    # This shifts the input towards the asymptotic regime of 1, where the output is larger.
    return float(np.sqrt(x))


def R(y_orig, y_new):
    # The output should increase (or remain equal within a tiny numerical tolerance)
    return y_new >= y_orig - 1e-9
